   1 | /**
   2 |  * Money helpers.
   3 |  *
   4 |  * Every function except add() is total. add() rejects a currency mismatch by
   5 |  * throwing, because silently picking one of the two currencies would corrupt a
   6 |  * total rather than fail it.
   7 |  */
   8 | 
   9 | export interface Money {
  10 |     amount: number;
  11 |     currency: string;
  12 | }
  13 | 
  14 | export function roundMoney(value: number): number {
  15 |     return Math.round(value * 100) / 100;
  16 | }
  17 | 
  18 | export function add(a: Money, b: Money): Money {
  19 |     if (a.currency !== b.currency) {
  20 |         throw new Error(`cannot add ${a.currency} to ${b.currency}`);
  21 |     }
  22 |     return { amount: roundMoney(a.amount + b.amount), currency: a.currency };
  23 | }
  24 | 
  25 | export function format(money: Money | null | undefined): string {
  26 |     if (!money) {
  27 |         return "-";
  28 |     }
  29 |     return `${roundMoney(money.amount).toFixed(2)} ${money.currency}`;
  30 | }
  31 | 
  32 | export function isPositive(money: Money | null | undefined): boolean {
  33 |     return money !== null && money !== undefined && money.amount > 0;
