   1 | /**
   2 |  * Forwards chat messages from a socket-like emitter to a handler.
   3 |  * After detach() the bridge must stop forwarding: the handler may already be disposed.
   4 |  */
   5 | 
   6 | class EventBridge {
   7 |     constructor(handler) {
   8 |         this.handler = handler;
   9 |         this.emitter = null;
  10 |         this.forwarded = 0;
  11 |     }
  12 | 
  13 |     onMessage(message) {
  14 |         this.forwarded += 1;
  15 |         this.handler.handle(message);
  16 |     }
  17 | 
  18 |     attach(emitter) {
  19 |         this.emitter = emitter;
  20 |         emitter.on("message", this.onMessage.bind(this));
  21 |     }
  22 | 
  23 |     detach() {
  24 |         if (!this.emitter) {
  25 |             return;
  26 |         }
  27 |         this.emitter.off("message", this.onMessage.bind(this));
  28 |         this.emitter = null;
  29 |     }
  30 | 
  31 |     stats() {
  32 |         return { attached: this.emitter !== null, forwarded: this.forwarded };
  33 |     }
  34 | }
  35 | 
  36 | module.exports = { EventBridge };
