   9 | 
  10 |     constructor(private readonly store: QuotaStore, private readonly limit: number) {}
  11 | 
  12 |     consume(account: string, bytes: number): Promise<boolean> {
  13 |         const previous = this.queues.get(account) ?? Promise.resolve();
  14 |         const next = previous.catch(() => undefined).then(async () => {
  15 |             const used = await this.store.used(account);
  16 |             if (used + bytes > this.limit) {
  17 |                 return false;
  18 |             }
  19 |             await this.store.setUsed(account, used + bytes);
  20 |             return true;
  21 |         });
  22 |         this.queues.set(account, next);
  23 |         void next.finally(() => {
  24 |             if (this.queues.get(account) === next) {
  25 |                 this.queues.delete(account);
  26 |             }
  27 |         }).catch(() => undefined);
  28 |         return next;
  29 |     }
  30 | }
