   1 | export interface BucketState {
   2 |     tokens: number;
   3 |     updatedAt: number;
   4 | }
   5 | 
   6 | export interface BucketStore {
   7 |     get(key: string): Promise<BucketState | undefined>;
   8 |     set(key: string, state: BucketState): Promise<void>;
