  10 | 
  11 | /**
  12 |  * Per-client rate limiter used by the API gateway for every incoming request.
  13 |  * A client may make at most `capacity` requests per refill window.
  14 |  */
  15 | export class TokenBucket {
  16 |     constructor(
  17 |         private readonly store: BucketStore,
  18 |         private readonly capacity: number,
  19 |         private readonly refillPerSecond: number
  20 |     ) {}
  21 | 
  22 |     async take(clientId: string, now = Date.now()): Promise<boolean> {
  23 |         const state = (await this.store.get(clientId)) ?? { tokens: this.capacity, updatedAt: now };
  24 |         const elapsed = Math.max(0, now - state.updatedAt) / 1000;
  25 |         const tokens = Math.min(this.capacity, state.tokens + elapsed * this.refillPerSecond);
  26 |         if (tokens < 1) {
  27 |             await this.store.set(clientId, { tokens, updatedAt: now });
  28 |             return false;
  29 |         }
  30 |         await this.store.set(clientId, { tokens: tokens - 1, updatedAt: now });
  31 |         return true;
  32 |     }
  33 | 
  34 |     async remaining(clientId: string, now = Date.now()): Promise<number> {
  35 |         const state = await this.store.get(clientId);
  36 |         if (!state) {
  37 |             return this.capacity;
  38 |         }
  39 |         const elapsed = Math.max(0, now - state.updatedAt) / 1000;
  40 |         return Math.floor(Math.min(this.capacity, state.tokens + elapsed * this.refillPerSecond));
  41 |     }
  42 | }
